class TestExtractErrorMessage:
    """Tests for _extract_error_message helper."""

    def test_extract_standard(self):
        msg = analytics_cog._extract_error_message(
            "ValueError: something broke", "ValueError"
        )
        assert msg == "something broke"

    def test_extract_with_traceback(self):
        tb = (
            'Traceback (most recent call last):\n'
            '  File "foo.py", line 10, in bar\n'
            '    baz()\n'
            'KeyError: \'missing_key\''
        )
        msg = analytics_cog._extract_error_message(tb, "KeyError")
        assert msg == "'missing_key'"

    def test_extract_no_message(self):
        msg = analytics_cog._extract_error_message("ValueError", "ValueError")
        assert msg == "ValueError"

    def test_extract_empty_tb(self):
        msg = analytics_cog._extract_error_message("", "TypeError")
        assert msg == "TypeError"

    def test_extract_no_tb(self):
        msg = analytics_cog._extract_error_message(None, "TypeError")
        assert msg == "TypeError"

    def test_extract_last_line_without_exc_type(self):
        tb = 'Traceback (most recent call last):\n  File "x.py", line 1, in f\n    raise\nRuntimeError: boom'
        msg = analytics_cog._extract_error_message(tb, "RuntimeError")
        assert msg == "boom"


