class TestHumanTimestamp:
    """Tests for _human_timestamp helper (deterministic, time-independent)."""

    FIXED_NOW = datetime(2026, 7, 8, 14, 30, 0)  # Jul 8, 2:30 PM UTC

    def _call(self, delta):
        ts = (self.FIXED_NOW + delta).isoformat()
        return analytics_cog._human_timestamp(ts, _now=self.FIXED_NOW)

    def test_just_now(self):
        result = self._call(timedelta())
        assert result == "just now"

    def test_minutes_ago(self):
        result = self._call(timedelta(minutes=-5))
        assert result == "5 min ago"

    def test_hours_ago_same_day(self):
        """3 hours ago on the same day → 'Today' format."""
        result = self._call(timedelta(hours=-3))
        assert result.startswith("Today")

    def test_crosses_day(self):
        """30 hours ago → 'Yesterday'."""
        result = self._call(timedelta(hours=-30))
        assert result.startswith("Yesterday")

    def test_none_input(self):
        assert analytics_cog._human_timestamp(None) == "?"

    def test_empty_input(self):
        assert analytics_cog._human_timestamp("") == "?"

    def test_today_format(self):
        """2 hours ago on the same day → 'Today'."""
        result = self._call(timedelta(hours=-2))
        assert result.startswith("Today")

    def test_yesterday_format(self):
        """26 hours ago → 'Yesterday'."""
        result = self._call(timedelta(hours=-26))
        assert result.startswith("Yesterday")

    def test_older_format(self):
        """5 days ago → absolute date, no 'ago'/'Today'/'Yesterday'."""
        result = self._call(timedelta(days=-5))
        assert "ago" not in result
        assert "Today" not in result
        assert "Yesterday" not in result


